//! Secret config vault.
//!
//! Every value the networking / attribution / WebView layer needs that must
//! NOT appear as a plaintext literal in the shipped binary lives here as an
//! obfuscated byte array. The keystream that unlocks them is generated by the
//! embedded stack VM (see [`crate::secure`]), so the decoder logic does not
//! exist as ordinary machine code — only the generic XOR loop does.
//!
//! Swift never holds any of these constants; it asks for them by id over the
//! C ABI (`rt_cfg_resolve`) and receives the already-decoded UTF-8 string.
//!
//! To rotate secrets: edit the plaintext table in
//! `examples/vault_encode.rs`, run `cargo run --example vault_encode -p
//! taycoon_engine`, and paste the printed arrays below. The round-trip test
//! at the bottom of this file guards against a mismatch between the host-side
//! encoder ([`fold`]) and the VM-side decoder ([`reveal`]).

use safetynet::{Typed, VmLayout, safetynet};

/// Project-unique keystream seed. Rotate per build.
pub const VAULT_SEED: u64 = 0x5256_5459_4146_3130;

#[derive(Clone, Copy, VmLayout)]
pub struct GSeed {
    pub seed: u64,
    pub index: u64,
}

/// One keystream byte for position `index`. Lowered into VM bytecode so the
/// derivation never appears as native code. 32-bit-masked throughout to stay
/// inside the VM's integer semantics (mirrors `secure::q2`).
#[safetynet]
#[allow(clippy::assign_op_pattern)]
pub fn gkeystream(input: GSeed) -> u64 {
    let seed: u64 = input.seed.typed::<u64>();
    let index: u64 = input.index.typed::<u64>();
    let mut lo: u64 = (seed ^ 2166136261) & 4294967295;
    let mut hi: u64 = ((seed >> 32) ^ 2654435761) & 4294967295;
    lo = (lo ^ ((index * 40503) & 4294967295)) & 4294967295;
    hi = (hi ^ ((index * 2246822519) & 4294967295)) & 4294967295;
    let mut i: u64 = 0;
    while i < 8 {
        lo = (lo * 1664525 + 1013904223 + hi) & 4294967295;
        hi = (hi ^ ((lo << 7) & 4294967295) ^ (lo >> 11)) & 4294967295;
        hi = (hi * 2891336453 + 12345) & 4294967295;
        i = i + 1;
    }
    (lo ^ hi) & 255
}

/// Host-side mirror of [`gkeystream`] in ordinary Rust. This is the single
/// source of truth for the *encoder* (`examples/vault_encode.rs`) and is kept
/// honest against the VM decoder by [`tests::vm_matches_plain`]. It is NOT used
/// on the decode path at runtime.
pub fn ks_plain(seed: u64, index: u64) -> u8 {
    let mut lo: u64 = (seed ^ 2166136261) & 0xffff_ffff;
    let mut hi: u64 = ((seed >> 32) ^ 2654435761) & 0xffff_ffff;
    lo = (lo ^ ((index.wrapping_mul(40503)) & 0xffff_ffff)) & 0xffff_ffff;
    hi = (hi ^ ((index.wrapping_mul(2246822519)) & 0xffff_ffff)) & 0xffff_ffff;
    for _ in 0..8 {
        lo = (lo.wrapping_mul(1664525).wrapping_add(1013904223).wrapping_add(hi)) & 0xffff_ffff;
        hi = (hi ^ ((lo << 7) & 0xffff_ffff) ^ (lo >> 11)) & 0xffff_ffff;
        hi = (hi.wrapping_mul(2891336453).wrapping_add(12345)) & 0xffff_ffff;
    }
    ((lo ^ hi) & 255) as u8
}

/// Encode a plaintext string into the obfuscated byte array stored below.
/// Used only by the offline encoder example and the round-trip test.
pub fn fold(value: &str) -> Vec<u8> {
    value
        .bytes()
        .enumerate()
        .map(|(i, b)| b ^ ks_plain(VAULT_SEED, i as u64))
        .collect()
}

/// VM-backed decode: the runtime path. The keystream comes from the VM, the
/// XOR loop is generic.
fn reveal(encoded: &[u8]) -> String {
    let bytes: Vec<u8> = encoded
        .iter()
        .enumerate()
        .map(|(i, b)| {
            b ^ (gkeystream(GSeed {
                seed: VAULT_SEED,
                index: i as u64,
            }) as u8)
        })
        .collect();
    String::from_utf8_lossy(&bytes).into_owned()
}

// ─── Secret ids (must stay in sync with Swift `RemoteKey`) ──────────────────
pub const ID_ENDPOINT: u32 = 0; // config endpoint URL
pub const ID_AF_KEY: u32 = 1; // AppsFlyer dev key
pub const ID_FIREBASE_SENDER: u32 = 2; // Firebase project number (GCM_SENDER_ID)
pub const ID_GCD_BASE: u32 = 3; // AppsFlyer GCD install_data base
pub const ID_PRIVACY: u32 = 4; // privacy policy URL
pub const ID_SUPPORT: u32 = 5; // support URL
pub const ID_UA_PRODUCT: u32 = 6; // "Mozilla/5.0"
pub const ID_UA_PLATFORM_PREFIX: u32 = 7; // "(iPhone; CPU iPhone OS"
pub const ID_UA_PLATFORM_SUFFIX: u32 = 8; // "like Mac OS X)"
pub const ID_UA_ENGINE: u32 = 9; // "AppleWebKit/605.1.15 (KHTML, like Gecko)"
pub const ID_UA_SAFARI_VERSION: u32 = 10; // "26.0"
