pub const ID_UA_SAFARI_TAIL: u32 = 12; // "604.1"
pub const ID_STORE_ID: u32 = 13; // numeric App Store id
pub const ID_STORAGE_PREFIX: u32 = 14; // persistence key namespace
pub const ID_LAUNCH_ROUTE_KEY: u32 = 15; // cold-start push UserDefaults key
pub const ID_PROBE_HOST_A: u32 = 16; // DNS reachability host 1
pub const ID_PROBE_HOST_B: u32 = 17; // DNS reachability host 2
pub const ID_PUSH_URL_KEYS: u32 = 18; // comma-joined list of push payload URL field names
pub const ID_PUSH_SKIP_KEYS: u32 = 19; // comma-joined list of APNs bookkeeping keys
pub const ID_PUSH_SNOOZE: u32 = 20; // "Not Now" cooldown seconds (ASCII decimal)
pub const ID_BODY_KEYS: u32 = 21; // ordered CSV of config body field names
pub const ID_OS_VALUE: u32 = 22; // "iOS" (platform value in body)
pub const ID_HDR_JSON: u32 = 23; // "application/json" (Content-Type/Accept)
pub const ID_HDR_AUTH: u32 = 24; // "Bearer " (GCD Authorization prefix)
