pub const ID_WEB_COLD_SETTLE_MS: u32 = 34; // cold-tap viewport settle delay (ms)
pub const ID_WEB_REDIRECT_RETRY: u32 = 35; // redirect-loop retry ceiling
pub const ID_WEB_NET_RETRY: u32 = 36; // transient network retry ceiling

// ─── Encoded secrets (paste from `cargo run --example vault_encode`) ───────
// GENERATED — do not hand-edit. Empty arrays decode to "" and keep the vault
// inert until real credentials are pasted in.
include!("vault_values.rs");

/// Resolve a secret by id into its plaintext (decoded via the VM keystream).
pub fn resolve(id: u32) -> String {
    let array: &[u8] = match id {
        ID_ENDPOINT => ENC_ENDPOINT,
        ID_AF_KEY => ENC_AF_KEY,
        ID_FIREBASE_SENDER => ENC_FIREBASE_SENDER,
        ID_GCD_BASE => ENC_GCD_BASE,
        ID_PRIVACY => ENC_PRIVACY,
        ID_SUPPORT => ENC_SUPPORT,
        ID_UA_PRODUCT => ENC_UA_PRODUCT,
        ID_UA_PLATFORM_PREFIX => ENC_UA_PLATFORM_PREFIX,
        ID_UA_PLATFORM_SUFFIX => ENC_UA_PLATFORM_SUFFIX,
        ID_UA_ENGINE => ENC_UA_ENGINE,
        ID_UA_SAFARI_VERSION => ENC_UA_SAFARI_VERSION,
        ID_UA_MOBILE_TOKEN => ENC_UA_MOBILE_TOKEN,
        ID_UA_SAFARI_TAIL => ENC_UA_SAFARI_TAIL,
        ID_STORE_ID => ENC_STORE_ID,
        ID_STORAGE_PREFIX => ENC_STORAGE_PREFIX,
        ID_LAUNCH_ROUTE_KEY => ENC_LAUNCH_ROUTE_KEY,
        ID_PROBE_HOST_A => ENC_PROBE_HOST_A,
        ID_PROBE_HOST_B => ENC_PROBE_HOST_B,
        ID_PUSH_URL_KEYS => ENC_PUSH_URL_KEYS,
        ID_PUSH_SKIP_KEYS => ENC_PUSH_SKIP_KEYS,
        ID_PUSH_SNOOZE => ENC_PUSH_SNOOZE,
        ID_BODY_KEYS => ENC_BODY_KEYS,
        ID_OS_VALUE => ENC_OS_VALUE,
        ID_HDR_JSON => ENC_HDR_JSON,
        ID_HDR_AUTH => ENC_HDR_AUTH,
        ID_WEB_SCHEMES => ENC_WEB_SCHEMES,
        ID_PROBE_HOST_C => ENC_PROBE_HOST_C,
        ID_CFG_TIMEOUT => ENC_CFG_TIMEOUT,
        ID_PROBE_TIMEOUT_MS => ENC_PROBE_TIMEOUT_MS,
        ID_WEB_INJECTION => ENC_WEB_INJECTION,
        ID_JS_REFLOW => ENC_JS_REFLOW,
        ID_JS_FOCUS => ENC_JS_FOCUS,
        ID_WEB_REFLOW_DELAYS => ENC_WEB_REFLOW_DELAYS,
        ID_WEB_POST_FINISH_MS => ENC_WEB_POST_FINISH_MS,
        ID_WEB_COLD_SETTLE_MS => ENC_WEB_COLD_SETTLE_MS,
        ID_WEB_REDIRECT_RETRY => ENC_WEB_REDIRECT_RETRY,
        ID_WEB_NET_RETRY => ENC_WEB_NET_RETRY,
        _ => &[],
    };
    reveal(array)
}

/// Parses the decoded secret as a non-negative integer. Returns 0 on failure,
/// which is also how callers signal "value absent" without a separate flag.
/// Useful for numeric tunables (snooze seconds, poll counts) that must not
/// appear as plaintext numeric literals in the Swift binary either.
pub fn resolve_number(id: u32) -> u64 {
    resolve(id).parse::<u64>().unwrap_or(0)
}

/// The vault stays inert until the config endpoint, the AppsFlyer dev key and
/// the Firebase project number are all present.
pub fn ready() -> bool {
    !resolve(ID_ENDPOINT).is_empty()
        && !resolve(ID_AF_KEY).is_empty()
        && !resolve(ID_FIREBASE_SENDER).is_empty()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn vm_matches_plain() {
        // The VM keystream must equal the host mirror for every position we
        // could ever encode, or fold()/reveal() silently corrupt secrets.
        // Covers the full length of the WebView injection bundle (>1 KB).
        for i in 0..4096u64 {
            let vm = gkeystream(GSeed {
                seed: VAULT_SEED,
                index: i,
            }) as u8;
            assert_eq!(vm, ks_plain(VAULT_SEED, i), "keystream mismatch at {i}");
        }
    }

    #[test]
    fn round_trip_sample() {
        let samples = [
            "https://example.com/config.php",
            "Mozilla/5.0",
            "(iPhone; CPU iPhone OS",
            "6824470855",
            "",
        ];
        for s in samples {
            assert_eq!(reveal(&fold(s)), s);
        }
    }

    #[test]
    fn long_value_round_trip() {
        // A payload past the 512-byte window, mirroring the WebView bundle.
        let blob: String = (0..1800).map(|i| ((i % 90) as u8 + 33) as char).collect();
        assert_eq!(reveal(&fold(&blob)), blob);
    }

    #[test]
    fn web_injection_decodes() {
        let js = resolve(ID_WEB_INJECTION);
        assert!(js.starts_with("(function()"));
        assert!(js.contains("__q7v"));
        assert!(js.contains("MutationObserver"));
    }
}
